public class ReverseList {
    static class ListNode {
        int val;
        ListNode next;
        ListNode(int v) { this.val = v; }
    }

    // 迭代版：三指针，时间 O(n)、空间 O(1)
    public ListNode reverseIterative(ListNode head) {
        ListNode prev = null;
        ListNode curr = head;
        while (curr != null) {
            ListNode next = curr.next; // 先保存后继，防止断链
            curr.next = prev;          // 反向指针
            prev = curr;
            curr = next;
        }
        return prev; // prev 即新头
    }

    // 递归版：时间 O(n)、空间 O(n)（调用栈深度 = 链长）
    public ListNode reverseRecursive(ListNode head) {
        if (head == null || head.next == null) {
            return head; // 空链表或只有一个节点，直接返回
        }
        ListNode newHead = reverseRecursive(head.next);
        head.next.next = head; // 后一个节点反向指回自己
        head.next = null;      // 断开旧方向，避免成环
        return newHead;
    }

    // 用例
    public static void main(String[] args) {
        ReverseList sol = new ReverseList();
        ListNode head = new ListNode(1);
        head.next = new ListNode(2);
        head.next.next = new ListNode(3);
        ListNode r1 = sol.reverseIterative(head); // 3 -> 2 -> 1
        System.out.println(sol.reverseRecursive(null)); // null，边界安全
    }
}

import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;

public class LRUCache {
    private final int capacity;
    private final LinkedHashMap<Integer, Integer> map;

    public LRUCache(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("capacity 必须为正数");
        }
        this.capacity = capacity;
        // accessOrder=true：访问（get/put 命中）后把条目移到链表尾部
        this.map = new LinkedHashMap<Integer, Integer>(capacity, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<Integer, Integer> eldest) {
                return size() > LRUCache.this.capacity; // 超容量自动淘汰最老条目
            }
        };
    }

    public int get(int key) {
        Integer v = map.get(key); // 命中即触发 afterNodeAccess，刷新为最近使用
        return v == null ? -1 : v;
    }

    public void put(int key, int value) {
        map.put(key, value); // 已存在则更新并刷新顺序；超限由 removeEldestEntry 淘汰
    }

    // 用例
    public static void main(String[] args) {
        LRUCache cache = new LRUCache(2);
        cache.put(1, 1);
        cache.put(2, 2);
        System.out.println(cache.get(1)); // 1，键 1 刷新为最近使用
        cache.put(3, 3);                  // 容量超限，淘汰最久未使用的键 2
        System.out.println(cache.get(2)); // -1
        System.out.println(cache.get(3)); // 3
    }
}
